script:
(function () {
  'use strict';
  // ===== Tax figures: tax year 2026 =====
  // Ordinary brackets, standard deductions and capital gains breakpoints: IRS Rev. Proc. 2025-32,
  // sections 4.01, 4.03 and 4.14 (2026 inflation adjustments, as amended by P.L. 119-21).
  // Net investment income tax: IRC section 1411, 3.8% of the smaller of net investment income or
  // MAGI over the threshold; thresholds are statutory and not indexed.
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj: [24800, 100800, 211400, 403550, 512450, 768700],
    hoh: [17700, 67450, 105700, 201750, 256200, 640600],
    mfs: [12400, 50400, 105700, 201775, 256225, 384350]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { // taxable income where the 0% rate ends and the 15% rate ends
    single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850]
  };
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var NIIT_RATE = 0.038, NIIT_THRESHOLD = { single: 200000, hoh: 200000, mfj: 250000, mfs: 125000 };
  // ======================================
  // Method: the Qualified Dividends and Capital Gain Tax Worksheet. Taxable income = other income
  // + all dividends - deductions; qualified dividends sit on top at 0/15/20%, the rest is taxed at
  // the ordinary brackets (tax = smaller of that and regular tax on everything). The dividend tax is
  // the federal tax with dividends minus the tax without them, plus NIIT and the state rate.
  // MAGI for NIIT is approximated as other income + dividends (no foreign exclusions).
  // Checked in Node (scratch tests, by hand): single, $60,000 other, $16,100 deduction, $12,000
  //   dividends of which $10,000 qualified -> taxable $55,900; ordinary tax on $45,900 = $5,260;
  //   $3,550 of qualified at 0% and $6,450 at 15% = $967.50; without dividends tax on $43,900 =
  //   $5,020 -> $240 (12% of $2,000) + $967.50 = $1,207.50. Single $250,000 other + $20,000
  //   qualified -> 15% = $3,000 + NIIT 3.8% x $20,000 = $760. MFJ $0 other, $80,000 qualified,
  //   $32,200 deduction -> taxable $47,800, all at 0%. Rate-table check: single $92,000 = $14,952.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var STATUS_NAMES = { single: 'Single', mfj: 'Married filing jointly', mfs: 'Married filing separately', hoh: 'Head of household' };

  function ordinaryTax(income, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }

  // Ordinary-rate bands that the slice of income from `from` to `to` falls into.
  function ordinarySlices(from, to, status) {
    var limits = BRACKETS[status], out = [], lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      var amt = Math.max(0, Math.min(to, upper) - Math.max(from, lower));
      if (amt > 0) out.push({ rate: RATES[i], amount: amt });
      lower = upper;
    }
    return out;
  }

  function dividendTax(p) {
    var nonQual = p.total - p.qualified;
    var taxable = Math.max(0, p.other + p.total - p.deduction);
    var taxableWithout = Math.max(0, p.other - p.deduction);
    var pref = Math.min(p.qualified, taxable), base = taxable - pref;
    var b = CG_BREAKS[p.status];
    var zero = Math.max(0, Math.min(taxable, b[0]) - base);
    var mid = Math.max(0, Math.min(taxable, b[1]) - Math.max(base, b[0]));
    var top = Math.max(0, taxable - Math.max(base, b[1]));
    var withDiv = Math.min(ordinaryTax(base, p.status) + 0.15 * mid + 0.20 * top, ordinaryTax(taxable, p.status));
    var without = ordinaryTax(taxableWithout, p.status);
    var fed = withDiv - without;
    var ordTax = ordinaryTax(base, p.status) - without;
    var qualTax = fed - ordTax;
    var magi = p.other + p.total;
    var niit = NIIT_RATE * Math.max(0, Math.min(p.total + p.invest, magi - NIIT_THRESHOLD[p.status]));
    // Only the dividends' share of NIIT: the tax with them minus the tax without them.
    var niitWithout = NIIT_RATE * Math.max(0, Math.min(p.invest, p.other - NIIT_THRESHOLD[p.status]));
    var niitDiv = niit - niitWithout;
    var state = p.total * p.stateRate;
    var allOrdinary = ordinaryTax(taxable, p.status) - without;
    return {
      nonQual: nonQual, taxable: taxable, fed: fed, ordTax: ordTax, qualTax: qualTax, niit: niitDiv, state: state,
      total: fed + niitDiv + state, saved: Math.max(0, allOrdinary - fed),
      ordSlices: ordinarySlices(taxableWithout, base, p.status), zero: zero, mid: mid, top: top
    };
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function pctText(r) { return (Math.round(r * 1000) / 10) + '%'; }

  var lastStatus = 'single';
  function update() {
    var status = document.getElementById('dtStatus').value;
    var dedEl = document.getElementById('dtDeduction');
    // Keep the deduction in step with the filing status while it still shows a standard amount.
    if (status !== lastStatus && parseFloat(dedEl.value) === STANDARD_DEDUCTION[lastStatus]) dedEl.value = String(STANDARD_DEDUCTION[status]);
    lastStatus = status;
    set('dtDeductionHint', TAX_YEAR + ' standard deduction for your filing status: ' + whole.format(STANDARD_DEDUCTION[status]) +
        '. Enter your itemized total if larger.');
    var p = { status: status, total: num('dtTotal'), qualified: num('dtQualified'), other: num('dtOther'),
              deduction: num('dtDeduction'), invest: num('dtInvest'), stateRate: num('dtState') };
    if (isNaN(p.invest)) p.invest = 0;
    if (isNaN(p.stateRate)) p.stateRate = 0;
    var error = document.getElementById('dtError');
    var bad = [p.total, p.qualified, p.other, p.deduction].some(isNaN) || p.total < 0 || p.qualified < 0 ||
              p.other < 0 || p.deduction < 0 || p.invest < 0 || p.stateRate < 0 || p.stateRate > 20 || p.qualified > p.total;
    error.hidden = !bad;
    if (bad) {
      error.textContent = p.qualified > p.total ? 'Qualified dividends are part of total ordinary dividends, so they cannot be larger.'
        : 'Enter amounts of 0 or more and a state rate from 0 to 20%.';
      return;
    }
    p.stateRate /= 100;
    var r = dividendTax(p);
    set('dtTax', money.format(r.total));
    set('dtRate', p.total > 0 ? pctText(r.total / p.total) : '–');
    set('dtAfter', money.format(p.total - r.total));
    set('dtQualTax', money.format(r.qualTax));
    set('dtOrdTax', money.format(r.ordTax));
    set('dtNiit', money.format(r.niit));
    set('dtStateTax', money.format(r.state));
    set('dtTaxable', whole.format(r.taxable));
    set('dtSaved', money.format(r.saved));

    var rows = [];
    function row(label, rate, amt, tax) {
      rows.push('<tr><td>' + label + '</td><td>' + rate + '</td><td>' + money.format(amt) + '</td><td>' + money.format(tax) + '</td></tr>');
    }
    var sheltered = r.nonQual + p.qualified - r.ordSlices.reduce(function (s, x) { return s + x.amount; }, 0) - r.zero - r.mid - r.top;
    if (sheltered > 0.005) row('Covered by deductions', '0%', sheltered, 0);
    r.ordSlices.forEach(function (s) { row('Nonqualified', pctText(s.rate), s.amount, s.amount * s.rate); });
    if (r.zero > 0) row('Qualified', '0%', r.zero, 0);
    if (r.mid > 0) row('Qualified', '15%', r.mid, r.mid * 0.15);
    if (r.top > 0) row('Qualified', '20%', r.top, r.top * 0.20);
    if (r.niit > 0) row('Net investment income tax', '3.8%', r.niit / NIIT_RATE, r.niit);
    if (r.state > 0) row('State', pctText(p.stateRate), p.total, r.state);
    if (!rows.length) rows.push('<tr><td colspan="4">Enter your dividends to see how they are taxed.</td></tr>');
    document.getElementById('dtBands').innerHTML = rows.join('');

    document.getElementById('dtRates').innerHTML = ['single', 'mfj', 'mfs', 'hoh'].map(function (s) {
      return '<tr><td>' + STATUS_NAMES[s] + '</td><td>' + whole.format(CG_BREAKS[s][0]) + '</td><td>' + whole.format(CG_BREAKS[s][1]) +
             '</td><td>' + whole.format(CG_BREAKS[s][1]) + '</td><td>' + whole.format(NIIT_THRESHOLD[s]) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('dtForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
